print('actual generated outputs absent BUILT_SOURCES', sorted({f.stem+'.inc' for f in (r/'src/xbeachlibrary/templates').glob('*.mako')}-set(b['autotools']['built_sources'])))
assert {x['name'] for x in g['outputs']}=={f.stem+'.inc' for f in (r/'src/xbeachlibrary/templates').glob('*.mako')}
for ev in c['source_evidence']:
 raw=Path(ev['path']).read_bytes();length=len(raw.split(b'\\n'))-(1 if raw.endswith(b'\\n') else 0)
 if ev['line_end']>length:print('OUT OF BOUNDS:',ev['path'],ev['line_start'],ev['line_end'],'actual last line',length)
for f in b['src_files']:
 if not f['path'].lower().endswith('.f90'):continue
 lines=(r/f['path']).read_bytes().split(b'\\n')
